1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  /** Zero-based index of the quote step that created the policy. */
30	  policy: number;
31	  incident: Incident;
32	}
33	
34	export type Step = QuoteStep | ClaimStep;
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export type StepResult = QuoteResult | ClaimResult;
51	
52	export interface ScenarioResults {
53	  results: StepResult[];
54	}
55	
56	/**
57	 * A customer as they stand at one point in a scenario: who they are, plus what
58	 * they have already been quoted. `quotesSoFar` counts *quotes priced*, not
59	 * steps taken — once claim steps exist the two will differ, and it is the quote
60	 * count that decides whether a policy is a follow-up contract.
61	 */
62	interface CustomerStanding {
63	  readonly customer: Customer;
64	  readonly quotesSoFar: number;
65	}
66	
67	const PROCESSING_FEE = 5;
68	
69	/**
70	 * The spec keeps intermediate amounts as exact fractions and rounds only the
71	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
72	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
73	 *
74	 * So percentages are applied as integer rationals — multiply by the numerator
75	 * first, divide by the denominator last — and money is carried in hundredths
76	 * of a G. Both operands of every product stay integral, so no drift accrues.
77	 */
78	const SUBUNITS_PER_G = 100;
79	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
80	
81	/**
82	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
83	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
84	 * numerator. Modifiers are summed onto a base, never multiplied through it.
85	 */
86	interface Rate {
87	  num: number;
88	  den: number;
89	}
90	
91	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
92	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
93	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
94	
95	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
96	const FOLLOW_UP_DISCOUNT: Rate = { num: -15, den: 100 };
97	
98	/** An item is highly enchanted from this level upwards. */
99	const HIGH_ENCHANTMENT_LEVEL = 5;
100	
101	/** A customer is long-standing from this many years of business upwards. */
102	const LOYALTY_YEARS = 2;
103	
104	/** The modifier amount `rate` contributes against `subunits` — not the total. */
105	const rateAmount = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
106	
107	/** Premiums round up — in the MHPCO's favour. */
108	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
109	
110	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
111	  sword: 100,
112	  amulet: 60,
113	  staff: 80,
114	  potion: 40,
115	  rune: 25,
116	  moonstone: 25,
117	};
118	
119	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
120	
121	/** What an item is insured for — distinct from what it costs to insure. */
122	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
123	  sword: 1000,
124	  amulet: 600,
125	  staff: 800,
126	  potion: 400,
127	  rune: 250,
128	  moonstone: 250,
129	};
130	
131	const insuranceValueOf = (item: Item): number => INSURANCE_VALUE_BY_ITEM_TYPE[item.type] ?? 0;
132	
133	const COMPONENT_TYPES = ["rune", "moonstone"];
134	
135	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
136	
137	/** Exactly this many alike components form a block, priced as one unit. */
138	const COMPONENT_BLOCK_SIZE = 3;
139	const COMPONENT_BLOCK_PREMIUM = 60;
140	
141	/** Splits items into those matching the predicate and those that do not. */
142	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
143	  items.filter(matches),
144	  items.filter((item) => !matches(item)),
145	];
146	
147	const groupByType = (items: Item[]): Map<string, Item[]> => {
148	  const groups = new Map<string, Item[]>();
149	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
150	
151	  return groups;
152	};
153	
154	const sumOfBasePremiums = (items: Item[]): number =>
155	  items.reduce((total, item) => total + basePremiumOf(item), 0);
156	
157	/**
158	 * Alike components — those of the very same type — form a block when there are
159	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
160	 * Any other count is priced per component.
161	 */
162	const componentGroupPremium = (group: Item[]): number =>
163	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
164	
165	/**
166	 * The policy base premium: every insured item's base premium, summed — except
167	 * that each group of alike components is priced as blocks where it can be.
168	 */
169	const policyBasePremiumOf = (items: Item[]): number => {
170	  const [components, mainItems] = partition(items, isComponent);
171	  const componentsTotal = [...groupByType(components).values()].reduce(
172	    (total, group) => total + componentGroupPremium(group),
173	    0,
174	  );
175	
176	  return sumOfBasePremiums(mainItems) + componentsTotal;
177	};
178	
179	/** The total the given rates contribute against a shared base. */
180	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
181	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
182	
183	const isHighlyEnchanted = (item: Item): boolean =>
184	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
185	
186	/** Which item-specific modifiers an item attracts, by its own attributes. */
187	const ratesForItem = (item: Item): Rate[] => [
188	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
189	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
190	];
191	
192	const isLongStanding = (standing: CustomerStanding): boolean =>
193	  standing.customer.yearsWithMHPCO >= LOYALTY_YEARS;
194	
195	const holdsAnEarlierQuote = (standing: CustomerStanding): boolean => standing.quotesSoFar > 0;
196	
197	/** Which policy-wide modifiers a policy attracts, by the customer's standing. */
198	const ratesForPolicy = (standing: CustomerStanding): Rate[] => [
199	  FIRST_INSURANCE_SURCHARGE,
200	  ...(isLongStanding(standing) ? [LOYALTY_DISCOUNT] : []),
201	  ...(holdsAnEarlierQuote(standing) ? [FOLLOW_UP_DISCOUNT] : []),
202	];
203	
204	/** Item-specific modifiers apply to the affected item's own base premium. */
205	const sumOfItemModifierAmounts = (items: Item[]): number =>
206	  items.reduce(
207	    (total, item) =>
208	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
209	    0,
210	  );
211	
212	/**
213	 * Modifiers are additive amounts, each computed against its own base: item
214	 * modifiers against the affected item, policy-wide modifiers against the
215	 * policy base premium. The processing fee is added at the very end.
216	 */
217	const quotePremium = (items: Item[], standing: CustomerStanding): number => {
218	  const policyBase = toSubunits(policyBasePremiumOf(items));
219	
220	  return toPremiumGold(
221	    policyBase +
222	      sumOfItemModifierAmounts(items) +
223	      sumOfRateAmounts(policyBase, ratesForPolicy(standing)) +
224	      toSubunits(PROCESSING_FEE),
225	  );
226	};
227	
228	/** A deductible is withheld from each damaged item's reimbursement. */
229	const DEDUCTIBLE = 100;
230	
231	/** The MHPCO pays at most this multiple of a policy's insurance sum. */
232	const CAP_MULTIPLE = 2;
233	
234	/** Payouts round down — in the MHPCO's favour. */
235	const toPayoutGold = (subunits: number): number => Math.floor(subunits / SUBUNITS_PER_G);
236	
237	/**
238	 * A policy created by a quote step: the items it covers, and how much of its
239	 * payout cap is still available.
240	 */
241	interface Policy {
242	  readonly items: Item[];
243	  readonly remainingCap: number;
244	}
245	
246	/**
247	 * What a policy insures for in total: every covered item's own insurance value,
248	 * summed. Unmodified — curses and enchantments move the premium, not this, and
249	 * a component block is a premium discount only.
250	 */
251	const insuranceSumOf = (items: Item[]): number =>
252	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
253	
254	const policyFor = (items: Item[]): Policy => ({
255	  items,
256	  remainingCap: toSubunits(insuranceSumOf(items) * CAP_MULTIPLE),
257	});
258	
259	/**
260	 * Damage to an item this heavily enchanted is reimbursed at half. Note this is
261	 * a different threshold from HIGH_ENCHANTMENT_LEVEL, which governs the premium.
262	 */
263	const HALF_REIMBURSEMENT_LEVEL = 8;
264	
265	/**
266	 * The share of the damage the MHPCO reimburses for an item. Clauses are a
267	 * priority selection rather than modifiers that stack: where more than one
268	 * could apply, the half-reimbursement clause wins.
269	 */
270	const reimbursedShareOf = (item: Item): Rate =>
271	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL
272	    ? { num: 50, den: 100 }
273	    : { num: 100, den: 100 };
274	
275	/**
276	 * What the MHPCO reimburses for one damaged item, before the cap is applied:
277	 * the reimbursed share of the damage, less the deductible.
278	 */
279	const reimbursementFor = (damage: Damage, item: Item): number =>
280	  rateAmount(toSubunits(damage.amount), reimbursedShareOf(item)) - toSubunits(DEDUCTIBLE);
281	
282	/** Everything a step may read and advance as the scenario runs. */
283	interface Ledger {
284	  readonly standing: CustomerStanding;
285	  /** Policies by the index of the quote step that created them. */
286	  readonly policies: ReadonlyMap<number, Policy>;
287	}
288	
289	/** The ledger as it stands once `policy` is on record at `stepIndex`. */
290	const withPolicy = (ledger: Ledger, stepIndex: number, policy: Policy): Ledger => ({
291	  ...ledger,
292	  policies: new Map(ledger.policies).set(stepIndex, policy),
293	});
294	
295	/**
296	 * The policy a step names, *assuming* the step names one that exists.
297	 *
298	 * No scenario yet reaches this with a dangling reference, so the assumption
299	 * holds for every case under test. It is stated here rather than asserted
300	 * silently at the call site; the todo tests for claims against absent or
301	 * mismatched policies are what will turn it into a checked failure.
302	 */
303	const assumePolicy = (ledger: Ledger, stepIndex: number): Policy => {
304	  const policy = ledger.policies.get(stepIndex);
305	  if (policy === undefined) throw new Error(`No policy created by step ${stepIndex}`);
306	
307	  return policy;
308	};
309	
310	/**
311	 * The insured item a damage entry refers to, *assuming* the policy covers one
312	 * of that type. Matching by type alone is enough while no policy under test
313	 * covers two alike items; the todo test for two swords is what will force a
314	 * damage entry to be paired with a particular one.
315	 */
316	const damagedItem = (policy: Policy, damage: Damage): Item => {
317	  const item = policy.items.find((covered) => covered.type === damage.itemType);
318	  if (item === undefined) throw new Error(`Policy does not cover a ${damage.itemType}`);
319	
320	  return item;
321	};
322	
323	/** The result of a step, and the ledger as the *next* step will find it. */
324	interface StepOutcome {
325	  readonly result: StepResult;
326	  readonly ledger: Ledger;
327	}
328	
329	/**
330	 * A quote prices the items against the customer's standing, and leaves the
331	 * customer holding one more quote than before — which is what makes the *next*
332	 * quote a follow-up. It also creates the policy that later claims draw on.
333	 */
334	const applyQuote = (step: QuoteStep, ledger: Ledger, stepIndex: number): StepOutcome => ({
335	  result: { premium: quotePremium(step.items, ledger.standing) },
336	  ledger: withPolicy(
337	    { ...ledger, standing: { ...ledger.standing, quotesSoFar: ledger.standing.quotesSoFar + 1 } },
338	    stepIndex,
339	    policyFor(step.items),
340	  ),
341	});
342	
343	/**
344	 * A claim reimburses each damaged item, less the deductible, and draws the
345	 * total down from the policy's remaining cap.
346	 */
347	const applyClaim = (step: ClaimStep, ledger: Ledger): StepOutcome => {
348	  const policy = assumePolicy(ledger, step.policy);
349	  const payout = step.incident.damages.reduce(
350	    (total, damage) => total + reimbursementFor(damage, damagedItem(policy, damage)),
351	    0,
352	  );
353	  const remainingCap = policy.remainingCap - payout;
354	
355	  return {
356	    result: { payout: toPayoutGold(payout), remainingCap: toPayoutGold(remainingCap) },
357	    ledger: withPolicy(ledger, step.policy, { ...policy, remainingCap }),
358	  };
359	};
360	
361	/**
362	 * Steps are processed in order, since a step's result can depend on those
363	 * before it — a quote is discounted once the customer holds an earlier one, and
364	 * a claim draws on a policy an earlier quote created.
365	 *
366	 * Each step both produces a result and hands on the ledger the next step will
367	 * see, so that a step's effect on later steps lives with the step's own logic
368	 * rather than in loose accumulators advanced by hand here.
369	 */
370	export const runScenario = (scenario: Scenario): ScenarioResults => {
371	  const results: StepResult[] = [];
372	  let ledger: Ledger = {
373	    standing: { customer: scenario.customer, quotesSoFar: 0 },
374	    policies: new Map(),
375	  };
376	
377	  scenario.steps.forEach((step, stepIndex) => {
378	    const outcome =
379	      step.op === "quote" ? applyQuote(step, ledger, stepIndex) : applyClaim(step, ledger);
380	    results.push(outcome.result);
381	    ledger = outcome.ledger;
382	  });
383	
384	  return { results };
385	};
